import bisect

def lis_length(nums: list[int]) -> int:
    if not nums:
        return 0

    tails = []
    for x in nums:
        idx = bisect.bisect_left(tails, x)
        if idx < len(tails):
            tails[idx] = x
        else:
            tails.append(x)

    return len(tails)
