import re

def calc(expr: str) -> float:
    # Tokenize the expression
    # Tokens: numbers (including .5), operators (+, -, *, /, **, (, )), unary signs
    tokens = re.findall(r'\d*\.\d+|\d+\.\d*|\d+|[\+\-\*\/\(\)\*\*]', expr)

    # Re-process tokens to handle the double asterisk ** correctly
    # The regex above might split ** into * and * if not careful, 
    # but the pattern [\+\-\*\/\(\)\*\*] is a bit ambiguous in regex.
    # Let's use a more robust tokenizer.
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue
        if expr[i:i+2] == '**':
            tokens.append('**')
            i += 2
        elif expr[i] in '+-*/()':
            tokens.append(expr[i])
            i += 1
        elif expr[i].isdigit() or expr[i] == '.':
            start = i
            while i < len(expr) and (expr[i].isdigit() or expr[i] == '.'):
                i += 1
            tokens.append(expr[start:i])
        else:
            i += 1

    pos = 0

    def parse_expression():
        nonlocal pos
        node = parse_term()
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                node += right
            else:
                node -= right
        return node

    def parse_term():
        nonlocal pos
        node = parse_exponent()
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right = parse_exponent()
            if op == '*':
                node *= right
            else:
                node /= right
        return node

    def parse_exponent():
        nonlocal pos
        node = parse_unary()
        if pos < len(tokens) and tokens[pos] == '**':
            pos += 1
            # Exponentiation is right-associative
            right = parse_exponent()
            node = node ** right
        return node

    def parse_unary():
        nonlocal pos
        if pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            val = parse_unary()
            return val if op == '+' else -val
        return parse_primary()

    def parse_primary():
        nonlocal pos
        token = tokens[pos]
        if token == '(':
            pos += 1
            val = parse_expression()
            pos += 1  # skip ')'
            return val
        else:
            pos += 1
            return float(token)

    return float(parse_expression())
