def num_decodings(s: str) -> int:
    MOD = 1_000_000_007
    n = len(s)
    if n == 0:
        return 0

    # dp[i] represents the number of ways to decode the prefix s[:i]
    # We only need the last two states to save space: dp[i-1] and dp[i-2]
    # prev2 is dp[i-2], prev1 is dp[i-1]
    prev2 = 1  # Base case: empty string

    # Initial state for dp[1]
    if s[0] == '*':
        prev1 = 9
    elif s[0] == '0':
        return 0
    else:
        prev1 = 1

    if n == 1:
        return prev1

    for i in range(1, n):
        current = 0
        char = s[i]
        prev_char = s[i-1]

        # Case 1: Single digit decoding (s[i])
        if char == '*':
            current = (current + 9 * prev1) % MOD
        elif char != '0':
            current = (current + prev1) % MOD

        # Case 2: Two digit decoding (s[i-1]s[i])
        if prev_char == '*':
            if char == '*':
                # '**' can be 11-19 (9 ways) or 21-26 (6 ways) = 15 ways
                current = (current + 15 * prev2) % MOD
            else:
                # '*digit'
                # If digit is 0-6, '*' can be 1 or 2 (2 ways)
                # If digit is 7-9, '*' can only be 1 (1 way)
                d = int(char)
                if d <= 6:
                    current = (current + 2 * prev2) % MOD
                else:
                    current = (current + prev2) % MOD
        elif prev_char == '1':
            if char == '*':
                # '1*' can be 11-19 (9 ways)
                current = (current + 9 * prev2) % MOD
            else:
                # '1digit' is always valid
                current = (current + prev2) % MOD
        elif prev_char == '2':
            if char == '*':
                # '2*' can be 21-26 (6 ways)
                current = (current + 6 * prev2) % MOD
            else:
                # '2digit' is valid if digit <= 6
                if int(char) <= 6:
                    current = (current + prev2) % MOD

        if current == 0 and prev1 == 0: # Optimization: if no ways to reach here
            return 0

        prev2 = prev1
        prev1 = current

    return prev1
