class DisjointSetUnion:
    def __init__(self, n):
        self.parent = list(range(n))
        self.count = 0

    def find(self, i):
        if self.parent[i] == i:
            return i
        self.parent[i] = self.find(self.parent[i])
        return self.parent[i]

    def union(self, i, j):
        root_i = self.find(i)
        root_j = self.find(j)
        if root_i != root_j:
            self.parent[root_i] = root_j
            self.count -= 1
            return True
        return False

def islands_after_adds(rows: int, cols: int, positions: list[tuple[int, int]]) -> list[int]:
    # Using iterative find to avoid recursion depth issues in large grids
    parent = list(range(rows * cols))

    def find(i):
        root = i
        while parent[root] != root:
            root = parent[root]
        while parent[i] != root:
            next_node = parent[i]
            parent[i] = root
            i = next_node
        return root

    grid = [False] * (rows * cols)
    num_islands = 0
    results = []

    for r, c in positions:
        idx = r * cols + c
        if not grid[idx]:
            grid[idx] = True
            num_islands += 1

            # Check 4 neighbors
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    n_idx = nr * cols + nc
                    if grid[n_idx]:
                        root_idx = find(idx)
                        root_n = find(n_idx)
                        if root_idx != root_n:
                            parent[root_idx] = root_n
                            num_islands -= 1

        results.append(num_islands)

    return results
