import re

def parse_json(text: str) -> object:
    index = 0
    length = len(text)

    def skip_whitespace():
        nonlocal index
        while index < length and text[index] in ' \t\n\r':
            index += 1

    def parse_value():
        skip_whitespace()
        if index >= length:
            raise ValueError("Unexpected end of input")

        char = text[index]
        if char == '{':
            return parse_object()
        elif char == '[':
            return parse_array()
        elif char == '"':
            return parse_string()
        elif char == 't':
            return parse_literal('true', True)
        elif char == 'f':
            return parse_literal('false', False)
        elif char == 'n':
            return parse_literal('null', None)
        elif char == '-' or char.isdigit():
            return parse_number()
        else:
            raise ValueError(f"Unexpected character: {char}")

    def parse_literal(literal, value):
        nonlocal index
        if text.startswith(literal, index):
            index += len(literal)
            return value
        raise ValueError(f"Expected {literal}")

    def parse_string():
        nonlocal index
        index += 1  # skip opening quote
        result = []
        while index < length:
            char = text[index]
            if char == '"':
                index += 1
                return "".join(result)
            elif char == '\\':
                index += 1
                if index >= length:
                    raise ValueError("Unterminated string escape")
                esc = text[index]
                if esc == '"': result.append('"')
                elif esc == '\\': result.append('\\')
                elif esc == '/': result.append('/')
                elif esc == 'b': result.append('\b')
                elif esc == 'f': result.append('\f')
                elif esc == 'n': result.append('\n')
                elif esc == 'r': result.append('\r')
                elif esc == 't': result.append('\t')
                elif esc == 'u':
                    index += 1
                    hex_str = text[index:index+4]
                    if len(hex_str) < 4 or not all(c in '0123456789abcdefABCDEF' for c in hex_str):
                        raise ValueError("Invalid unicode escape")
                    result.append(chr(int(hex_str, 16)))
                    index += 4
                else:
                    raise ValueError(f"Invalid escape: \\{esc}")
            elif char in '\n\r':
                raise ValueError("Unterminated string: newline in string")
            else:
                result.append(char)
            index += 1
        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal index
        start = index
        if text[index] == '-':
            index += 1

        if index >= length or not text[index].isdigit():
            raise ValueError("Invalid number")

        # Leading zero check
        if text[index] == '0':
            index += 1
            if index < length and text[index].isdigit():
                raise ValueError("Leading zeros not allowed")
        else:
            while index < length and text[index].isdigit():
                index += 1

        is_float = False
        if index < length and text[index] == '.':
            is_float = True
            index += 1
            if index >= length or not text[index].isdigit():
                raise ValueError("Invalid decimal fraction")
            while index < length and text[index].isdigit():
                index += 1

        if index < length and text[index] in 'eE':
            is_float = True
            index += 1
            if index < length and text[index] == '-':
                index += 1
            if index >= length or not text[index].isdigit():
                raise ValueError("Invalid exponent")
            while index < length and text[index].isdigit():
                index += 1

        num_str = text[start:index]
        try:
            return float(num_str) if is_float else int(num_str)
        except ValueError:
            raise ValueError(f"Invalid number: {num_str}")

    def parse_array():
        nonlocal index
        index += 1  # skip [
        arr = []
        skip_whitespace()
        if index < length and text[index] == ']':
            index += 1
            return arr

        while True:
            arr.append(parse_value())
            skip_whitespace()
            if index < length and text[index] == ']':
                index += 1
                return arr
            elif index < length and text[index] == ',':
                index += 1
                skip_whitespace()
                if index < length and text[index] == ']':
                    raise ValueError("Trailing comma in array")
            else:
                raise ValueError("Expected , or ] in array")

    def parse_object():
        nonlocal index
        index += 1  # skip {
        obj = {}
        skip_whitespace()
        if index < length and text[index] == '}':
            index += 1
            return obj

        while True:
            skip_whitespace()
            if index >= length or text[index] != '"':
                raise ValueError("Expected string key in object")
            key = parse_string()
            skip_whitespace()
            if index >= length or text[index] != ':':
                raise ValueError("Expected : after key")
            index += 1
            obj[key] = parse_value()
            skip_whitespace()
            if index < length and text[index] == '}':
                index += 1
                return obj
            elif index < length and text[index] == ',':
                index += 1
                skip_whitespace()
                if index < length and text[index] == '}':
                    raise ValueError("Trailing comma in object")
            else:
                raise ValueError("Expected , or } in object")

    result = parse_value()
    skip_whitespace()
    if index < length:
        raise ValueError("Trailing characters after JSON")
    return result
