def words_to_number(text: str) -> int:
    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14,
        'fifteen': 15, 'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19
    }
    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }
    scales = {
        'hundred': 100,
        'thousand': 1000,
        'million': 1000000,
        'billion': 1000000000
    }

    is_negative = False
    if text.startswith('minus '):
        is_negative = True
        text = text[6:]

    # Replace hyphens with spaces and split into tokens
    tokens = text.replace('-', ' ').split()

    total = 0
    current_segment = 0

    for token in tokens:
        if token == 'and':
            continue
        elif token in units:
            current_segment += units[token]
        elif token in tens:
            current_segment += tens[token]
        elif token == 'hundred':
            current_segment *= 100
        elif token in scales:
            scale_val = scales[token]
            # If we hit a large scale (thousand+), multiply current segment and add to total
            # Note: 'hundred' is handled locally to current_segment
            current_segment *= scale_val
            total += current_segment
            current_segment = 0
        else:
            continue

    total += current_segment
    return -total if is_negative else total
