import heapq
from collections import deque

def topo_order(n: int, edges: list[tuple[int, int]]) -> list[int] | None:
    adj = [[] for _ in range(n)]
    in_degree = [0] * n

    # Build adjacency list and calculate in-degrees
    for u, v in edges:
        adj[u].append(v)
        in_degree[v] += 1

    # To get the lexicographically smallest order, use a Min-Heap
    # instead of a standard Queue in Kahn's algorithm.
    pq = []
    for i in range(n):
        if in_degree[i] == 0:
            heapq.heappush(pq, i)

    result = []
    while pq:
        u = heapq.heappop(pq)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(pq, v)

    # If result contains all nodes, no cycle exists
    if len(result) == n:
        return result
    else:
        return None
