from collections import deque, defaultdict

def alien_order(words: list[str]) -> str:
    adj = defaultdict(set)
    in_degree = {char: 0 for word in words for char in word}

    # Build the graph
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i+1]
        min_len = min(len(w1), len(w2))

        # Check for prefix edge case: ['abc', 'ab'] is invalid
        if len(w1) > len(w2) and w1[:min_len] == w2[:min_len]:
            return ""

        for j in range(min_len):
            if w1[j] != w2[j]:
                if w2[j] not in adj[w1[j]]:
                    adj[w1[j]].add(w2[j])
                    in_degree[w2[j]] += 1
                break

    # Kahn's algorithm with a Min-Heap to ensure lexicographically smallest result
    # However, the problem asks for the lexicographically smallest string 
    # among all valid topological sorts. This requires a Min-Heap.
    import heapq

    queue = [char for char in in_degree if in_degree[char] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        char = heapq.heappop(queue)
        result.append(char)

        for neighbor in adj[char]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(queue, neighbor)

    if len(result) < len(in_degree):
        return ""

    return "".join(result)
