import re

def eval_bool(expr: str, env: dict[str, bool]) -> bool:
    # Tokenize the expression
    # Tokens: '(', ')', 'not', 'and', 'or', 'true', 'false', or identifiers
    token_specification = [
        ('LITERAL', r'true|false'),
        ('OP',      r'not|and|or'),
        ('LPAREN',  r'\('),
        ('RPAREN',  r'\)'),
        ('ID',      r'[a-zA-Z_][a-zA-Z0-9_]*'),
        ('SKIP',    r'[ \t\n\r]+'),
        ('MISMATCH',r'.'),
    ]
    tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)
    tokens = []
    for mo in re.finditer(tok_regex, expr):
        kind = mo.lastgroup
        value = mo.group()
        if kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise ValueError(f'Unexpected character {value}')
        tokens.append((kind, value))

    pos = 0

    def peek():
        nonlocal pos
        return tokens[pos] if pos < len(tokens) else (None, None)

    def consume(expected_kind=None):
        nonlocal pos
        kind, value = peek()
        if expected_kind and kind != expected_kind:
            raise ValueError(f"Expected {expected_kind} but got {kind}")
        pos += 1
        return value

    def parse_expression():
        # Or is lowest precedence
        return parse_or()

    def parse_or():
        node = parse_and()
        while peek()[1] == 'or':
            consume()
            right = parse_and()
            node = node or right
        return node

    def parse_and():
        node = parse_not()
        while peek()[1] == 'and':
            consume()
            right = parse_not()
            node = node and right
        return node

    def parse_not():
        if peek()[1] == 'not':
            consume()
            return not parse_not()
        else:
            return parse_primary()

    def parse_primary():
        kind, value = peek()
        if kind == 'LPAREN':
            consume('LPAREN')
            result = parse_expression()
            consume('RPAREN')
            return result
        elif kind == 'LITERAL':
            consume()
            return value == 'true'
        elif kind == 'ID':
            consume('ID')
            if value not in env:
                raise KeyError(value)
            return env[value]
        else:
            raise ValueError(f"Unexpected token: {value}")

    result = parse_expression()
    if pos < len(tokens):
        raise ValueError("Trailing tokens in expression")
    return result
